const dest = JSON.parse(fs.readFileSync(destPath, "utf8"));
dest.strings = dest.strings || {};

// Copy page titles into string keys
if (dest.pages) {
  for (const meta of Object.values(dest.pages)) {
    if (meta.title && meta.title.en) {
      dest.strings[meta.title.en] = dest.strings[meta.title.en] || {
        bn: meta.title.bn,
        hi: meta.title.hi,
      };
    }
  }
}

let added = 0;
for (const [en, tr] of Object.entries(map)) {
  dest.strings[en] = tr;
  added += 1;
}

const still = missing.filter((s) => !dest.strings[s]);
for (const s of still) {
  dest.strings[s] = { bn: s, hi: s };
}

fs.writeFileSync(destPath, JSON.stringify(dest, null, 2) + "\n", "utf8");
console.log("merged", added, "translations; identity leftovers", still.length);
if (still.length) still.forEach((s) => console.log("ID", s.slice(0, 80)));
